using Godot;
using System;
public partial class MigrationScene {
 Node3D BlueprintStructure(BuildPiece p,bool preview){if(p.Def.Opening!="")return OpeningStructure(p,preview);var root=new Node3D{Position=new((float)p.X,(float)p.Y,(float)p.Z),RotationDegrees=new(0,(float)p.Yaw,0)};var d=p.Def;float w=(float)d.W,h=(float)d.H,z=(float)d.D;Color timber=new(.39f,.28f,.17f),metal=new(.31f,.38f,.37f),accent=new(.67f,.55f,.27f),cloth=new(.28f,.34f,.27f),cyan=new(.20f,.58f,.53f);bool solid=!preview;
  void Part(Vector3 pos,Vector3 size,Color color,bool collide=false){Bevel(root,pos,size,color);if(solid&&collide)PhysicsObstacle(root,new BoxShape3D{Size=size},pos);}
  void Leg(float x,float depth,float top)=>Part(new(x,top/2,depth),new(.12f,top,.12f),metal,true);
  if(d.Name=="Cabin doorway"){float opening=1.1f;for(int side=-1;side<=1;side+=2)Part(new(side*(w+opening)/4,h/2,0),new((w-opening)/2,h,z),timber,true);Part(new(0,h-.13f,0),new(opening,.26f,z),timber,true);var door=new Node3D{Position=new(-opening/2,0,0),RotationDegrees=new(0,p.Open?95:0,0)};root.AddChild(door);Box(door,new(opening/2,(h-.26f)/2,0),new(opening,h-.26f,z*.65f),timber,solid&&!p.Open);for(int i=0;i<3;i++)Box(door,new(opening/2,.3f+i*.75f,-z/2),new(opening,.07f,.05f),metal);Box(door,new(opening-.1f,1.1f,-z/2-.03f),new(.07f,.05f,.08f),accent);return root;}
  switch(d.Function){
   case "decor-table":for(int a=-1;a<=1;a+=2)for(int b=-1;b<=1;b+=2)Leg(a*w*.4f,b*z*.35f,h-.1f);Part(new(0,h-.06f,0),new(w,.12f,z),d.Tier==1?timber:metal,true);Part(new(-.25f,h+.025f,0),new(.30f,.05f,.22f),cloth);Tube(root,new(.35f,h,0),new(.35f,h+.14f,0),.06f,accent);break;
   case "decor-stool":for(int a=-1;a<=1;a+=2)for(int b=-1;b<=1;b+=2)Leg(a*w*.3f,b*z*.3f,h-.08f);Part(new(0,h-.04f,0),new(w,.08f,z),timber,true);break;
   case "decor-rug":Part(new(0,h/2,0),new(w,h,z),cloth);for(int i=-3;i<=3;i++)Part(new(i*w/8,h+.003f,0),new(.04f,.006f,z*.9f),accent);break;
   case "decor-shelf":for(int a=-1;a<=1;a+=2)Part(new(a*(w/2-.04f),h/2,0),new(.08f,h,z),timber,true);for(int j=0;j<3;j++){float y=.12f+j*h*.42f;Part(new(0,y,0),new(w,.08f,z),timber,true);for(int i=0;i<3;i++)Part(new(-w*.3f+i*.20f,y+.13f,0),new(.10f,.20f,.18f),i==0?cloth:accent);}break;
   case "decor-lantern":Part(new(0,.06f,0),new(w,.12f,z),metal);Part(new(0,.28f,0),new(w*.65f,.25f,z*.65f),new(.93f,.65f,.27f));Part(new(0,.46f,0),new(w,.08f,z),metal);if(!preview)root.AddChild(new OmniLight3D{Position=new(0,.3f,0),LightColor=new(1,.68f,.32f),LightEnergy=.6f,OmniRange=4,ShadowEnabled=false});break;
   case "door":Part(new(-w/2+.07f,h/2,0),new(.14f,h,z),metal,true);Part(new(w/2-.07f,h/2,0),new(.14f,h,z),metal,true);Part(new(0,h-.08f,0),new(w,.16f,z),metal,true);var leaf=new Node3D{Position=new(-w/2+.14f,0,0),RotationDegrees=new(0,p.Open?95:0,0)};root.AddChild(leaf);Box(leaf,new((w-.28f)/2,h/2,0),new(w-.28f,h-.16f,z*.65f),d.Tier<3?timber:metal,solid&&!p.Open);Box(leaf,new(w-.45f,h*.48f,-z/2),new(.09f,.07f,.08f),accent);break;
   case "window":Part(new(0,.45f,0),new(w,.9f,z),timber,true);Part(new(0,h-.3f,0),new(w,.6f,z),timber,true);for(int s=-1;s<=1;s+=2)Part(new(s*(w/2-.25f),h/2,0),new(.5f,h,z),timber,true);Part(new(0,h/2,0),new(.07f,h*.45f,.1f),metal);break;
   case "storage":case "fridge":Part(new(0,h/2,0),new(w,h,z),d.Function=="fridge"?new(.61f,.65f,.56f):d.Tier>=3?metal:timber,true);for(int s=-1;s<=1;s+=2)Part(new(s*w*.35f,h/2,-z/2-.02f),new(.08f,h*.85f,.04f),metal);Part(new(0,h*.7f,-z/2-.05f),new(.24f,.05f,.06f),accent);if(d.Function=="fridge")Part(new(0,h*.72f,-z/2-.06f),new(w*.85f,.025f,.02f),metal);break;
   case "fence":case "electric":for(int s=-1;s<=1;s+=2)Leg(s*(w/2-.08f),0,h);for(int i=1;i<=4;i++)Part(new(0,h*i/5,0),new(w,.035f,.04f),d.Function=="electric"?cyan:timber);if(solid)PhysicsObstacle(root,new BoxShape3D{Size=new(w,h,.15f)},new(0,h/2,0));break;
   case "barrier":for(int i=0;i<7;i++){float x=(i-3)*w/7;Part(new(x,h/2,0),new(w/7-.025f,h,z*.5f),d.Tier<3?timber:metal,true);}for(int s=-1;s<=1;s+=2)Part(new(0,h*(s<0?.3f:.75f),-.2f),new(w,.10f,.12f),metal);break;
   case "spikes":case "trap":case "electrictrap":Part(new(0,.08f,0),new(w,.16f,z),timber);for(int a=-1;a<=1;a++)for(int b=-1;b<=1;b++)Tube(root,new(a*w*.3f,.1f,b*z*.3f),new(a*w*.3f+.12f,h,b*z*.3f),.07f,d.Function=="electrictrap"?cyan:metal,.008f);break;
   case "platform":for(int a=-1;a<=1;a+=2)for(int c=-1;c<=1;c+=2)Leg(a*w*.43f,c*z*.43f,h);Part(new(0,h-.1f,0),new(w,.2f,z),timber,true);for(int i=0;i<9;i++)Part(new(-w*.4f,h*i/9,0),new(.5f,.07f,.12f),metal,true);break;
   case "support":Part(new(0,h/2,0),new(w,h,z),metal,true);for(int i=0;i<5;i++)Part(new(0,h*i/5,0),new(w+.12f,.12f,z+.12f),accent);break;
   case "power":Part(new(0,.35f,0),new(w,.7f,z),metal,true);Part(new(-w*.2f,.8f,0),new(w*.4f,.4f,z*.65f),accent);for(int i=0;i<7;i++)Part(new(w*.23f,.25f+i*.07f,-z/2-.02f),new(w*.3f,.025f,.025f),new(.08f,.11f,.1f));Tube(root,new(-w*.25f,.8f,z*.2f),new(-w*.25f,h,z*.2f),.05f,metal);break;
   case "light":case "searchlight":case "alarm":case "lure":Leg(0,0,h*.8f);Part(new(0,h*.85f,0),new(w,.35f,z),d.Function=="alarm"?accent:metal);Part(new(0,h*.85f,-z*.52f),new(w*.7f,.20f,.03f),d.Function=="lure"?new(.55f,.20f,.15f):new(.78f,.74f,.51f));if(!preview&&Powered(p)&&d.Function is "light" or "searchlight")root.AddChild(new OmniLight3D{Position=new(0,h,0),LightColor=new(1,.83f,.55f),LightEnergy=2,OmniRange=d.Function=="searchlight"?25:12});break;
   case "turret":Leg(0,0,h*.65f);for(int s=-1;s<=1;s+=2)Tube(root,new(0,h*.4f,0),new(s*w*.4f,0,z*.35f),.06f,metal);Part(new(0,h*.8f,0),new(.45f,.25f,.65f),metal);for(int s=-1;s<=1;s+=2)Tube(root,new(s*.10f,h*.83f,-.25f),new(s*.10f,h*.83f,-1),.04f,metal);Part(new(.30f,h*.75f,0),new(.25f,.3f,.4f),accent);break;
   case "mobile":case "vehicle":Part(new(0,.55f,0),new(w,.45f,z),metal,true);Part(new(0,1.1f,z*.1f),new(w*.9f,h*.6f,z*.65f),cloth,true);Part(new(0,h*.8f,-z*.23f),new(w*.72f,.32f,.04f),new(.29f,.46f,.47f));for(int s=-1;s<=1;s+=2)for(int a=-1;a<=1;a+=2)Ellipsoid(root,new(s*w*.5f,.40f,a*z*.32f),new(.18f,.35f,.35f),new(.055f,.065f,.06f));Part(new(0,.72f,-z*.51f),new(w*.85f,.12f,.10f),accent);if(d.Function=="mobile")ArtSleepingBag(root);break;
   case "water":if(d.Tier==1){Part(new(0,.2f,0),new(.65f,.4f,.65f),metal,true);Tube(root,new(0,.35f,0),new(0,.65f,0),.22f,metal);}else{Tube(root,new(0,.12f,0),new(0,h*.85f,0),w*.4f,metal);Part(new(0,h*.9f,0),new(w,.12f,z),accent);Tube(root,new(w*.38f,.3f,0),new(w*.58f,.3f,0),.035f,metal);if(solid)PhysicsObstacle(root,new CylinderShape3D{Radius=w*.4f,Height=h*.85f},new(0,h*.42f,0));}break;
   case "food":for(int s=-1;s<=1;s+=2)Leg(s*w*.42f,0,h);Part(new(0,h,0),new(w,.08f,.10f),timber);for(int i=0;i<5;i++)Ellipsoid(root,new((i-2)*w*.14f,h*.7f,0),new(.06f,.18f,.04f),new(.42f,.23f,.15f));break;
   case "farm":Part(new(0,.12f,0),new(w,.24f,z),timber,true);Part(new(0,.25f,0),new(w*.9f,.04f,z*.9f),new(.18f,.13f,.08f));for(int a=-1;a<=1;a++)for(int c=-1;c<=1;c++){Tube(root,new(a*w*.25f,.26f,c*z*.25f),new(a*w*.25f,.8f,c*z*.25f),.018f,new(.31f,.47f,.20f));Ellipsoid(root,new(a*w*.25f,.6f,c*z*.25f),new(.12f,.08f,.12f),new(.38f,.55f,.22f));}if(d.Tier==4){for(int a=-1;a<=1;a+=2)for(int c=-1;c<=1;c+=2)Leg(a*w*.45f,c*z*.45f,h);Part(new(0,h,0),new(w,.08f,z),cloth);var glass=new StandardMaterial3D{AlbedoColor=new(.44f,.65f,.58f,.20f),Transparency=BaseMaterial3D.TransparencyEnum.Alpha,Roughness=.35f};foreach(int side in new[]{-1,1}){var pane=new MeshInstance3D{Mesh=new BoxMesh{Size=new(.03f,h-.3f,z*.9f)},Position=new(side*w*.45f,h/2,0),MaterialOverride=glass};root.AddChild(pane);if(solid)PhysicsObstacle(root,new BoxShape3D{Size=new(.03f,h-.3f,z*.9f)},pane.Position);}root.AddChild(new MeshInstance3D{Mesh=new BoxMesh{Size=new(w*.9f,h-.3f,.03f)},Position=new(0,h/2,z*.45f),MaterialOverride=glass});}break;
   case "bed":for(int a=-1;a<=1;a+=2)for(int c=-1;c<=1;c+=2)Leg(a*w*.4f,c*z*.4f,.35f);Part(new(0,.35f,0),new(w,.12f,z),metal,true);Part(new(0,.47f,0),new(w*.94f,.18f,z*.94f),cloth);Part(new(0,.59f,-z*.3f),new(w*.8f,.12f,.45f),new(.62f,.61f,.49f));break;case "medical":case "repair":case "cook":for(int a=-1;a<=1;a+=2)for(int c=-1;c<=1;c+=2)Leg(a*w*.4f,c*z*.4f,h*.75f);Part(new(0,h*.75f,0),new(w,.12f,z),metal,true);if(d.Function=="medical"){Part(new(0,h*.85f,0),new(w*.85f,.15f,z*.8f),new(.63f,.64f,.49f));Part(new(-w*.3f,h,.1f),new(.35f,.15f,.40f),cloth);Part(new(w*.25f,h,.1f),new(.25f,.22f,.2f),new(.73f,.70f,.57f));Part(new(w*.25f,h+.12f,.1f),new(.04f,.01f,.15f),new(.65f,.17f,.12f));if(d.Tier==5){Part(new(w*.4f,h+.45f,.1f),new(.05f,.50f,.05f),metal);Part(new(w*.4f,h+.7f,.1f),new(.30f,.20f,.05f),metal);Part(new(w*.4f,h+.7f,.07f),new(.24f,.14f,.01f),cyan);}}else if(d.Function=="repair"){ItemTool(root,2);Part(new(w*.25f,h,.1f),new(.4f,.3f,.35f),accent);}else{Tube(root,new(0,h*.8f,0),new(0,h*1.1f,0),.23f,metal);for(int i=0;i<5;i++)Part(new((i-2)*.13f,.12f,0),new(.10f,.15f,.6f),timber);}break;
  }return root;
 }
